insert into public.practice_exercises (id, slug, title, summary, skill, band_group, question_types, duration_minutes, question_count, passage, audio_path, audio_mime, audio_bytes, content_version, is_published, source_title, source_url, source_license, source_attribution) values ('f6799e26-d435-54f6-9e03-13d04d3b0ab7', 'voa-sleepy-teens-reading', 'Early Classes = Sleepy Teens', 'Đọc về giấc ngủ của thanh thiếu niên và giờ bắt đầu học.', 'reading', 'below_5', array['multiple_choice', 'true_false_not_given', 'gap_fill']::text[], 10, 5, array['A. Surveys of American teenagers find that about half of them do not get enough sleep on school nights. They get an average of sixty to ninety minutes less than experts say they need. One reason is biology. Experts say teens are programmed to go to sleep later and wake up later than other age groups. Yet many schools start classes as early as seven in the morning.', 'B. A clinical psychologist says teens need eight to ten hours of sleep a night. Sleepy teens can experience depression, and tired drivers can be dangerous. He says that starting classes later is one thing schools can do. Studies show that students can improve by a full letter grade in their first and second classes.', 'C. At St. George''s School, the head teacher tried a thirty-minute delay. Visits to the health centre by tired students decreased by half. Late arrivals to first period fell by a third. Students said that they were less sleepy during the day, and teachers noticed a more positive mood.']::text[], null, null, null, 2, true, 'Early Classes = Sleepy Teens (Duh!)', 'https://learningenglish.voanews.com/a/at-some-schools-later-classes--less-sleepy-teens-104438624/113705.html', 'Public domain', 'VOA Learning English');
