insert into public.practice_exercises (id, slug, title, summary, skill, band_group, question_types, duration_minutes, question_count, passage, audio_path, audio_mime, audio_bytes, content_version, is_published, source_title, source_url, source_license, source_attribution) values ('6f1adbaa-7162-58e6-a2f6-7365a00d8014', 'voa-test-anxiety-reading', 'Writing About Test Fears', 'Đọc nghiên cứu về lo lắng trước kỳ thi và một can thiệp ngắn.', 'reading', '5_6', array['matching_headings', 'multiple_choice', 'true_false_not_given', 'gap_fill']::text[], 14, 5, array['A. Some students get so nervous before a test that they do poorly even when they know the material. Psychology professor Sian Beilock says that worrying about consequences uses attention and memory resources that could otherwise be used to focus on the exam.', 'B. Beilock and researcher Gerardo Ramirez developed a possible solution. Just before an exam, anxious students spent ten minutes writing about their worries. In a study, students who sat quietly performed an average of twelve percent worse on a second test. Students who wrote about their fears improved by an average of five percent.', 'C. The researchers also worked with younger students in a biology class. Before final exams, students either wrote about their feelings or thought about unrelated things. Highly anxious students who did the writing received an average grade of B+, compared with a B- for those who did not. The researchers say students can also try the technique at home or in a library.']::text[], null, null, null, 2, true, 'Anxious Students Gain on Tests by Writing About Fears', 'https://learningenglish.voanews.com/a/anxious-students-gain-on-tests-by-writing-about-fears-114235749/113753.html', 'Public domain', 'VOA Learning English');
insert into public.practice_questions (id, exercise_id, position, type, instruction, prompt, options) values ('816419b0-db65-58d0-b4a2-81616e1c5b72', '6f1adbaa-7162-58e6-a2f6-7365a00d8014', 1, 'matching_headings', 'Choose the best heading for paragraph A.', 'Paragraph A', '["Why worry can affect test performance", "A new biology course", "How to mark an exam", "The cost of university"]'::jsonb);
insert into public.practice_questions (id, exercise_id, position, type, instruction, prompt, options) values ('fc5ba894-c436-57b8-96c9-8cea8762745c', '6f1adbaa-7162-58e6-a2f6-7365a00d8014', 2, 'multiple_choice', 'Choose ONE answer.', 'How long did students write about their worries?', '["Ten minutes", "Twelve minutes", "One hour"]'::jsonb);
