insert into public.practice_exercises (id, slug, title, summary, skill, band_group, question_types, duration_minutes, question_count, passage, audio_path, audio_mime, audio_bytes, content_version, is_published, source_title, source_url, source_license, source_attribution) values ('79993c6d-4adc-5fcc-afa1-3890f50b7216', 'voa-learning-from-failure-reading', 'Learning from Failure', 'Đọc về cách tổ chức học hỏi từ thất bại và thay đổi quyết định.', 'reading', '6_7', array['multiple_choice', 'true_false_not_given', 'matching_headings', 'gap_fill']::text[], 17, 5, array['A. A study says organizations learn more from failures than from successes, and keep that knowledge longer. Researchers Vinit Desai and Peter Madsen did not find much long-term organizational learning from success. They found that knowledge gained from failure can last for years.', 'B. The study looked at organizations that launch satellites and other space vehicles. In 2002, insulating material damaged a rocket on Atlantis, but the flight was considered a success. In 2003, insulation struck Columbia during launch. The shuttle broke apart on re-entry, seven crew members died, and NASA suspended flights while an investigation suggested changes.', 'C. Desai says searching for solutions after a failure can make leaders more open-minded. He points to airlines as an industry that has learned from failures. He advises organizations to look for useful information in small failures and failures they avoided, and to encourage the open sharing of information.']::text[], null, null, null, 2, true, 'How Failure Can Lead to Long-Lasting Knowledge', 'https://learningenglish.voanews.com/amp/sometimes-failure-leads-to-long-lasting-knowledge-102475329/113656.html', 'Public domain', 'VOA Learning English');
insert into public.practice_questions (id, exercise_id, position, type, instruction, prompt, options) values ('752d03e6-84c4-568d-b3e0-1828e0851648', '79993c6d-4adc-5fcc-afa1-3890f50b7216', 1, 'multiple_choice', 'Choose ONE answer.', 'What did the researchers find about knowledge from failure?', '["It can last for years.", "It is always ignored.", "It is less useful than success.", "It only applies to airlines."]'::jsonb);
insert into public.practice_questions (id, exercise_id, position, type, instruction, prompt, options) values ('e338c058-08af-5f92-9af4-47681bbd3bb0', '79993c6d-4adc-5fcc-afa1-3890f50b7216', 2, 'true_false_not_given', 'Choose TRUE, FALSE or NOT GIVEN.', 'The 2002 Atlantis flight was treated as a failure.', '["TRUE", "FALSE", "NOT GIVEN"]'::jsonb);
