insert into public.practice_exercises (id, slug, title, summary, skill, band_group, question_types, duration_minutes, question_count, passage, audio_path, audio_mime, audio_bytes, content_version, is_published, source_title, source_url, source_license, source_attribution) values ('778f8554-9e39-5be3-8052-75c4280d8127', 'voa-science-websites-reading', 'Science Websites for Children', 'Đọc về các nền tảng trực tuyến giúp trẻ em khám phá khoa học.', 'reading', '8_plus', array['multiple_choice', 'matching_headings', 'true_false_not_given', 'gap_fill']::text[], 21, 5, array['A. Millions of children use the Internet every day to explore the web, play games and research school projects. The Mad Science Group launched a science-based social network called Mad Science Kids Club. It was designed for children between six and fourteen and aimed to let them build an online community while exploring scientific discovery.', 'B. The club included groups such as a Counting Club for children who enjoy mathematics and Cosmic Adventures for those interested in space. One application allowed children to ask science questions that were published with answers from experts. The Science Zone offered experiments that children and parents could do at home.', 'C. The report also describes other sites. One explained science-related news in accessible language and added definitions of important words. Another offered guides for making toys from everyday materials and explained the scientific theories behind them. The report notes that such projects could provide many hours of exploration, although it had not tested every activity itself.']::text[], null, null, null, 2, true, 'New Science Websites for Children', 'https://learningenglish.voanews.com/a/new-science-websites-for-children-112524799/113713.html', 'Public domain', 'VOA Learning English');
